<?php
require_once '../config.php';require_once '../includes/helpers.php';require_once '../includes/kardex_export.php';
try{$context=kardex_export_context($_GET);$filename=kardex_export_filename($context);$temporary=tempnam(sys_get_temp_dir(),'kardex-');if($temporary===false)throw new RuntimeException('No se pudo preparar la exportación.');write_kardex_xlsx($context,$temporary);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.$filename.'"');header('Content-Length: '.filesize($temporary));header('X-Content-Type-Options: nosniff');readfile($temporary);unlink($temporary);}catch(InvalidArgumentException $e){http_response_code(422);header('Content-Type: text/plain; charset=utf-8');echo $e->getMessage();}catch(Throwable $e){if(isset($temporary)&&is_file($temporary))unlink($temporary);error_log($e->getMessage());http_response_code(500);header('Content-Type: text/plain; charset=utf-8');echo 'No se pudo generar el archivo Excel.';}exit;
